import 'dotenv/config';

function required(name) {
  const v = process.env[name];
  if (!v || v.startsWith('your-')) {
    throw new Error(`Missing or unset env var: ${name}. Edit .env and set it.`);
  }
  return v;
}

export const config = {
  token: required('DISCORD_TOKEN'),
  clientId: required('DISCORD_CLIENT_ID'),
  guildId: required('DISCORD_GUILD_ID'),
  botCommandsChannelId: required('BOT_COMMANDS_CHANNEL_ID'),
  ytdlpPath: process.env.YTDLP_PATH || 'yt-dlp',
  logLevel: process.env.LOG_LEVEL || 'info',
  admin: {
    port: parseInt(process.env.ADMIN_PORT || '8787', 10),
    user: process.env.ADMIN_USER || 'admin',
    password: process.env.ADMIN_PASSWORD || 'change-me',
    bind: process.env.ADMIN_BIND || '0.0.0.0',
    botService: process.env.BOT_SERVICE || 'discord-music-bot.service',
    adminService: process.env.ADMIN_SERVICE || 'discord-music-bot-admin.service',
  },
};

import pino from 'pino';
import { config } from './config.js';

export const logger = pino({
  level: config.logLevel,
  transport: process.stdout.isTTY
    ? { target: 'pino-pretty', options: { colorize: true, translateTime: 'SYS:HH:MM:ss' } }
    : undefined,
});

import { spawn } from 'node:child_process';
import { config } from '../config.js';
import { logger } from '../logger.js';

const URL_RE = /^https?:\/\//i;

function rewriteYouTubeMusic(url) {
  try {
    const u = new URL(url);
    if (u.hostname === 'music.youtube.com') {
      u.hostname = 'www.youtube.com';
      return u.toString();
    }
  } catch {}
  return url;
}

async function spotifyToSearchQuery(url) {
  // Spotify oEmbed returns { title: "Song Name - Artist" } with no auth required.
  try {
    const res = await fetch(`https://open.spotify.com/oembed?url=${encodeURIComponent(url)}`);
    if (!res.ok) throw new Error(`spotify oembed status ${res.status}`);
    const data = await res.json();
    if (data && data.title) return data.title;
  } catch (e) {
    logger.warn({ err: e?.message, url }, 'spotify oembed failed');
  }
  return null;
}

function runYtdlpJson(args) {
  return new Promise((resolve, reject) => {
    const proc = spawn(config.ytdlpPath, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    proc.stdout.on('data', (c) => (out += c));
    proc.stderr.on('data', (c) => (err += c));
    proc.on('error', reject);
    proc.on('close', (code) => {
      if (code !== 0) return reject(new Error(`yt-dlp exit ${code}: ${err.trim()}`));
      try {
        // For ytsearch1 yt-dlp returns one JSON line; for plain URL it returns one too.
        const firstLine = out.trim().split('\n').filter(Boolean)[0];
        if (!firstLine) return reject(new Error('yt-dlp returned no data'));
        resolve(JSON.parse(firstLine));
      } catch (e) {
        reject(new Error(`yt-dlp JSON parse failed: ${e.message}`));
      }
    });
  });
}

/**
 * Resolve a user query into a playable track descriptor.
 * Returns: { title, url, webpageUrl, durationSec, thumbnail, requestedBy, displayQuery }
 */
export async function resolveQuery(rawQuery, requestedBy) {
  let query = rawQuery.trim();
  let displayQuery = query;
  let target;

  if (URL_RE.test(query)) {
    if (/spotify\.com/i.test(query)) {
      const title = await spotifyToSearchQuery(query);
      if (title) {
        target = `ytsearch1:${title}`;
        displayQuery = `${title} (from Spotify)`;
      } else {
        target = `ytsearch1:${query}`;
      }
    } else {
      target = rewriteYouTubeMusic(query);
    }
  } else {
    target = `ytsearch1:${query}`;
  }

  const args = [
    '-j',
    '--no-playlist',
    '--no-warnings',
    '--default-search', 'ytsearch1',
    '--socket-timeout', '15',
    target,
  ];

  const info = await runYtdlpJson(args);

  return {
    title: info.title || info.fulltitle || 'Unknown title',
    webpageUrl: info.webpage_url || info.original_url || target,
    durationSec: info.duration ?? null,
    thumbnail: (info.thumbnails && info.thumbnails.length ? info.thumbnails[info.thumbnails.length - 1].url : info.thumbnail) || null,
    requestedBy,
    displayQuery,
  };
}

/** Spawn a yt-dlp process that streams the best audio to stdout. */
export function spawnAudioStream(webpageUrl) {
  const args = [
    '-o', '-',
    '-f', 'bestaudio[ext=webm]/bestaudio/best',
    '--no-playlist',
    '--no-warnings',
    '--quiet',
    '--no-part',
    '--no-progress',
    '--retries', '3',
    '--fragment-retries', '3',
    '--socket-timeout', '15',
    webpageUrl,
  ];
  const proc = spawn(config.ytdlpPath, args, { stdio: ['ignore', 'pipe', 'pipe'] });
  let stderrBuf = '';
  proc.stderr.on('data', (c) => {
    stderrBuf += c.toString();
    if (stderrBuf.length > 4096) stderrBuf = stderrBuf.slice(-4096);
  });
  proc.on('error', (e) => logger.error({ err: e.message }, 'yt-dlp stream spawn error'));
  proc.on('close', (code) => {
    if (code !== 0 && code !== null) {
      logger.warn({ code, tail: stderrBuf.slice(-500) }, 'yt-dlp stream exited non-zero');
    }
  });
  return proc;
}

export function formatDuration(sec) {
  if (sec == null || isNaN(sec)) return '--:--';
  const s = Math.floor(sec);
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const r = s % 60;
  if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}`;
  return `${m}:${String(r).padStart(2, '0')}`;
}

import {
  joinVoiceChannel,
  createAudioPlayer,
  createAudioResource,
  AudioPlayerStatus,
  VoiceConnectionStatus,
  StreamType,
  entersState,
  NoSubscriberBehavior,
} from '@discordjs/voice';
import { spawnAudioStream } from './resolver.js';
import { logger } from '../logger.js';

/**
 * Per-guild music state.
 */
class GuildMusic {
  constructor(guildId) {
    this.guildId = guildId;
    this.queue = [];           // array of track descriptors
    this.current = null;       // currently-playing track
    this.connection = null;
    this.player = null;
    this.textChannel = null;   // channel to post auto-messages into
    this.voiceChannelId = null;
    this.currentProc = null;   // yt-dlp child process for current track
    this.destroyed = false;
  }

  ensurePlayer() {
    if (this.player) return this.player;
    this.player = createAudioPlayer({
      behaviors: { noSubscriber: NoSubscriberBehavior.Pause },
    });
    this.player.on('error', (err) => {
      logger.error({ err: err.message, guildId: this.guildId }, 'audio player error');
      this._safeNotify(`Playback error: ${err.message}`);
      this._advance();
    });
    this.player.on(AudioPlayerStatus.Idle, () => {
      // Track finished naturally
      this._advance();
    });
    return this.player;
  }

  async connect(voiceChannel, textChannel) {
    this.textChannel = textChannel;
    if (this.connection && this.voiceChannelId === voiceChannel.id) return this.connection;

    if (this.connection) {
      try { this.connection.destroy(); } catch {}
      this.connection = null;
    }

    this.connection = joinVoiceChannel({
      channelId: voiceChannel.id,
      guildId: voiceChannel.guild.id,
      adapterCreator: voiceChannel.guild.voiceAdapterCreator,
      selfDeaf: true,
      selfMute: false,
    });
    this.voiceChannelId = voiceChannel.id;

    this.connection.on(VoiceConnectionStatus.Disconnected, async () => {
      try {
        await Promise.race([
          entersState(this.connection, VoiceConnectionStatus.Signalling, 5000),
          entersState(this.connection, VoiceConnectionStatus.Connecting, 5000),
        ]);
      } catch {
        // It's a real disconnect
        this.destroy();
      }
    });

    this.connection.subscribe(this.ensurePlayer());

    try {
      await entersState(this.connection, VoiceConnectionStatus.Ready, 15_000);
    } catch (e) {
      this.destroy();
      throw e;
    }
    return this.connection;
  }

  enqueue(track) {
    this.queue.push(track);
  }

  /** Start playing if idle. Safe to call repeatedly. */
  async maybeStart() {
    if (!this.player) return;
    if (this.current) return;
    if (this.queue.length === 0) return;
    await this._playNext();
  }

  async _playNext() {
    const next = this.queue.shift();
    if (!next) {
      this.current = null;
      return;
    }
    this.current = next;

    try {
      const proc = spawnAudioStream(next.webpageUrl);
      this.currentProc = proc;
      const resource = createAudioResource(proc.stdout, { inputType: StreamType.Arbitrary });
      this.ensurePlayer().play(resource);
      this._safeNotify(`Now playing: **${escapeMd(next.title)}**`);
    } catch (e) {
      logger.error({ err: e.message }, 'failed to start track');
      this._safeNotify(`Failed to play **${escapeMd(next.title)}**: ${e.message}`);
      this._advance();
    }
  }

  _advance() {
    this._killCurrentProc();
    this.current = null;
    if (this.queue.length === 0) {
      // Stay connected; idle is fine. (Stop command will disconnect.)
      return;
    }
    this._playNext();
  }

  _killCurrentProc() {
    if (this.currentProc) {
      try { this.currentProc.kill('SIGKILL'); } catch {}
      this.currentProc = null;
    }
  }

  skip() {
    const skipped = this.current;
    if (!skipped && this.queue.length === 0) return null;
    // Stopping the player triggers Idle -> _advance() naturally.
    if (this.player) this.player.stop(true);
    this._killCurrentProc();
    return skipped;
  }

  removeIndex(oneBased) {
    const i = oneBased - 1;
    if (i < 0 || i >= this.queue.length) return null;
    return this.queue.splice(i, 1)[0];
  }

  removeRange(startOne, endOne) {
    const start = Math.max(1, startOne) - 1;
    const end = Math.min(this.queue.length, endOne); // exclusive end after this
    if (start >= this.queue.length || end <= start) return [];
    return this.queue.splice(start, end - start);
  }

  stopAndLeave() {
    this.queue = [];
    this.current = null;
    this._killCurrentProc();
    if (this.player) {
      try { this.player.stop(true); } catch {}
    }
    if (this.connection) {
      try { this.connection.destroy(); } catch {}
      this.connection = null;
      this.voiceChannelId = null;
    }
  }

  destroy() {
    this.destroyed = true;
    this.stopAndLeave();
  }

  _safeNotify(msg) {
    if (!this.textChannel) return;
    this.textChannel.send({ content: msg }).catch((e) => {
      logger.warn({ err: e.message }, 'failed to send notify message');
    });
  }
}

function escapeMd(s) {
  return String(s).replace(/([*_~`>|\\])/g, '\\$1');
}

const guilds = new Map();

export function getMusic(guildId) {
  let g = guilds.get(guildId);
  if (!g) {
    g = new GuildMusic(guildId);
    guilds.set(guildId, g);
  }
  return g;
}

export function shutdownAll() {
  for (const g of guilds.values()) {
    try { g.destroy(); } catch {}
  }
  guilds.clear();
}

import { EmbedBuilder, ActionRowBuilder, ButtonBuilder, ButtonStyle } from 'discord.js';
import { formatDuration } from './resolver.js';

export function queueButtons(disabled = false) {
  return new ActionRowBuilder().addComponents(
    new ButtonBuilder()
      .setCustomId('music:skip')
      .setLabel('Skip')
      .setStyle(ButtonStyle.Primary)
      .setDisabled(disabled),
    new ButtonBuilder()
      .setCustomId('music:stop')
      .setLabel('Stop')
      .setStyle(ButtonStyle.Danger)
      .setDisabled(disabled),
  );
}

export function queueEmbed(music) {
  const embed = new EmbedBuilder().setColor(0x5865f2).setTitle('Music Queue');

  if (music.current) {
    embed.addFields({
      name: 'Now Playing',
      value: `**${truncate(music.current.title, 200)}** \`[${formatDuration(music.current.durationSec)}]\`\nrequested by <@${music.current.requestedBy}>`,
    });
  } else {
    embed.setDescription('Nothing is playing right now.');
  }

  if (music.queue.length > 0) {
    const lines = music.queue.slice(0, 25).map((t, i) => {
      const num = String(i + 1).padStart(2, ' ');
      return `\`${num}.\` **${truncate(t.title, 80)}** \`[${formatDuration(t.durationSec)}]\` — <@${t.requestedBy}>`;
    });
    let value = lines.join('\n');
    if (music.queue.length > 25) {
      value += `\n…and **${music.queue.length - 25}** more.`;
    }
    embed.addFields({ name: `Up Next (${music.queue.length})`, value });

    const totalSec = music.queue.reduce((a, t) => a + (t.durationSec || 0), 0);
    if (totalSec > 0) {
      embed.setFooter({ text: `Total queue length: ${formatDuration(totalSec)}` });
    }
  } else if (music.current) {
    embed.addFields({ name: 'Up Next', value: '_(empty)_' });
  }

  return embed;
}

function truncate(s, n) {
  s = String(s);
  return s.length <= n ? s : s.slice(0, n - 1) + '…';
}

import { SlashCommandBuilder, MessageFlags } from 'discord.js';
import { getMusic } from '../music/manager.js';
import { resolveQuery, formatDuration } from '../music/resolver.js';
import { logger } from '../logger.js';

export const data = new SlashCommandBuilder()
  .setName('play')
  .setDescription('Add a song to the queue')
  .addStringOption((o) =>
    o.setName('query')
      .setDescription('YouTube / YouTube Music / Spotify / SoundCloud URL, or keyword search')
      .setRequired(true),
  );

export async function execute(interaction) {
  const member = interaction.member;
  const voice = member?.voice?.channel;
  if (!voice) {
    return interaction.reply({ content: 'You need to be in a voice channel.', flags: MessageFlags.Ephemeral });
  }

  const query = interaction.options.getString('query', true);
  await interaction.deferReply();

  let track;
  try {
    track = await resolveQuery(query, interaction.user.id);
  } catch (e) {
    logger.warn({ err: e.message, query }, 'resolve failed');
    return interaction.editReply({ content: `Could not resolve **${truncate(query, 100)}**: ${e.message}` });
  }

  const music = getMusic(interaction.guildId);

  try {
    await music.connect(voice, interaction.channel);
  } catch (e) {
    return interaction.editReply({ content: `Could not join your voice channel: ${e.message}` });
  }

  music.enqueue(track);
  const position = music.current ? music.queue.length : 0;
  await music.maybeStart();

  const where = position === 0
    ? 'Now playing'
    : `Added to queue (position **#${position}**)`;
  await interaction.editReply({
    content: `${where}: **${truncate(track.title, 200)}** \`[${formatDuration(track.durationSec)}]\``,
  });
}

function truncate(s, n) {
  s = String(s);
  return s.length <= n ? s : s.slice(0, n - 1) + '…';
}

import { SlashCommandBuilder, MessageFlags } from 'discord.js';
import { getMusic } from '../music/manager.js';

export const data = new SlashCommandBuilder()
  .setName('skip')
  .setDescription('Skip the currently playing song');

export async function execute(interaction) {
  const music = getMusic(interaction.guildId);
  if (!music.current && music.queue.length === 0) {
    return interaction.reply({ content: 'Nothing is playing.', flags: MessageFlags.Ephemeral });
  }
  const skipped = music.skip();
  await interaction.reply({
    content: skipped ? `Skipped **${escapeMd(skipped.title)}**.` : 'Skipped.',
  });
}

function escapeMd(s) {
  return String(s).replace(/([*_~`>|\\])/g, '\\$1');
}

import { SlashCommandBuilder } from 'discord.js';
import { getMusic } from '../music/manager.js';
import { queueEmbed, queueButtons } from '../music/embeds.js';

export const data = new SlashCommandBuilder()
  .setName('queue')
  .setDescription('Show the current music queue');

export async function execute(interaction) {
  const music = getMusic(interaction.guildId);
  const empty = !music.current && music.queue.length === 0;
  await interaction.reply({
    embeds: [queueEmbed(music)],
    components: [queueButtons(empty)],
  });
}

import { SlashCommandBuilder } from 'discord.js';
import { getMusic } from '../music/manager.js';

export const data = new SlashCommandBuilder()
  .setName('stop')
  .setDescription('Clear the queue, stop playback, leave voice channel');

export async function execute(interaction) {
  const music = getMusic(interaction.guildId);
  const had = music.current || music.queue.length > 0;
  music.stopAndLeave();
  await interaction.reply({
    content: had ? 'Stopped, queue cleared, left the voice channel.' : 'Nothing to stop. Left voice channel if connected.',
  });
}

import { SlashCommandBuilder, MessageFlags } from 'discord.js';
import { getMusic } from '../music/manager.js';

export const data = new SlashCommandBuilder()
  .setName('remove')
  .setDescription('Remove an item or range from the queue')
  .addStringOption((o) =>
    o.setName('selector')
      .setDescription('Single position (e.g. "3") or inclusive range (e.g. "1-7")')
      .setRequired(true),
  );

export async function execute(interaction) {
  const sel = interaction.options.getString('selector', true).trim();
  const music = getMusic(interaction.guildId);

  if (music.queue.length === 0) {
    return interaction.reply({ content: 'The queue is empty.', flags: MessageFlags.Ephemeral });
  }

  const rangeMatch = sel.match(/^(\d+)\s*-\s*(\d+)$/);
  const singleMatch = sel.match(/^(\d+)$/);

  if (singleMatch) {
    const idx = parseInt(singleMatch[1], 10);
    const removed = music.removeIndex(idx);
    if (!removed) {
      return interaction.reply({ content: `No item at position **${idx}** (queue size: ${music.queue.length + 1}).`, flags: MessageFlags.Ephemeral });
    }
    return interaction.reply({ content: `Removed **#${idx}**: ${escapeMd(removed.title)}` });
  }

  if (rangeMatch) {
    let a = parseInt(rangeMatch[1], 10);
    let b = parseInt(rangeMatch[2], 10);
    if (a > b) [a, b] = [b, a];
    const removed = music.removeRange(a, b);
    if (removed.length === 0) {
      return interaction.reply({ content: `Nothing in range **${a}-${b}** to remove.`, flags: MessageFlags.Ephemeral });
    }
    return interaction.reply({
      content: `Removed **${removed.length}** item(s) from positions **${a}-${b}**.`,
    });
  }

  return interaction.reply({
    content: 'Selector must be a single number (e.g. `3`) or a range (e.g. `1-7`).',
    flags: MessageFlags.Ephemeral,
  });
}

function escapeMd(s) {
  return String(s).replace(/([*_~`>|\\])/g, '\\$1');
}

import { MessageFlags } from 'discord.js';
import { getMusic } from '../music/manager.js';
import { queueEmbed, queueButtons } from '../music/embeds.js';

export async function handleButton(interaction) {
  if (!interaction.customId.startsWith('music:')) return false;

  const action = interaction.customId.slice('music:'.length);
  const music = getMusic(interaction.guildId);

  if (action === 'skip') {
    if (!music.current && music.queue.length === 0) {
      return interaction.reply({ content: 'Nothing is playing.', flags: MessageFlags.Ephemeral });
    }
    const skipped = music.skip();
    await interaction.update({
      embeds: [queueEmbed(music)],
      components: [queueButtons(!music.current && music.queue.length === 0)],
    });
    if (skipped && interaction.channel) {
      interaction.channel.send({ content: `<@${interaction.user.id}> skipped **${escapeMd(skipped.title)}**.` }).catch(() => {});
    }
    return true;
  }

  if (action === 'stop') {
    music.stopAndLeave();
    await interaction.update({
      embeds: [queueEmbed(music)],
      components: [queueButtons(true)],
    });
    if (interaction.channel) {
      interaction.channel.send({ content: `<@${interaction.user.id}> stopped playback and cleared the queue.` }).catch(() => {});
    }
    return true;
  }

  return interaction.reply({ content: `Unknown action: ${action}`, flags: MessageFlags.Ephemeral });
}

function escapeMd(s) {
  return String(s).replace(/([*_~`>|\\])/g, '\\$1');
}

import { REST, Routes } from 'discord.js';
import { config } from './config.js';
import { data as play } from './commands/play.js';
import { data as skip } from './commands/skip.js';
import { data as queue } from './commands/queue.js';
import { data as stop } from './commands/stop.js';
import { data as remove } from './commands/remove.js';

const commands = [play, skip, queue, stop, remove].map((c) => c.toJSON());

const rest = new REST({ version: '10' }).setToken(config.token);

try {
  console.log(`Registering ${commands.length} guild commands to ${config.guildId}...`);
  const result = await rest.put(
    Routes.applicationGuildCommands(config.clientId, config.guildId),
    { body: commands },
  );
  console.log(`Registered ${Array.isArray(result) ? result.length : '?'} commands successfully.`);
  process.exit(0);
} catch (err) {
  console.error('Failed to register commands:', err);
  process.exit(1);
}

import { Client, GatewayIntentBits, Events, MessageFlags } from 'discord.js';
import { config } from './config.js';
import { logger } from './logger.js';
import { shutdownAll } from './music/manager.js';
import { handleButton } from './interactions/buttons.js';

import * as play from './commands/play.js';
import * as skip from './commands/skip.js';
import * as queueCmd from './commands/queue.js';
import * as stop from './commands/stop.js';
import * as remove from './commands/remove.js';

const commands = new Map([
  [play.data.name, play],
  [skip.data.name, skip],
  [queueCmd.data.name, queueCmd],
  [stop.data.name, stop],
  [remove.data.name, remove],
]);

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildVoiceStates,
  ],
});

client.once(Events.ClientReady, (c) => {
  logger.info({ tag: c.user.tag, id: c.user.id }, 'Discord client ready');
});

client.on(Events.InteractionCreate, async (interaction) => {
  try {
    if (interaction.isChatInputCommand()) {
      // Channel restriction: only respond inside the configured #bot-commands channel
      if (interaction.channelId !== config.botCommandsChannelId) {
        return interaction.reply({
          content: `Please use this command in <#${config.botCommandsChannelId}>.`,
          flags: MessageFlags.Ephemeral,
        });
      }
      const cmd = commands.get(interaction.commandName);
      if (!cmd) {
        return interaction.reply({ content: 'Unknown command.', flags: MessageFlags.Ephemeral });
      }
      await cmd.execute(interaction);
      return;
    }

    if (interaction.isButton()) {
      // Same channel restriction for buttons
      if (interaction.channelId !== config.botCommandsChannelId) {
        return interaction.reply({
          content: `Please use bot controls in <#${config.botCommandsChannelId}>.`,
          flags: MessageFlags.Ephemeral,
        });
      }
      await handleButton(interaction);
      return;
    }
  } catch (err) {
    logger.error({ err: err?.message, stack: err?.stack }, 'interaction handler crashed');
    if (interaction.isRepliable()) {
      const payload = { content: `Internal error: ${err?.message || 'unknown'}`, flags: MessageFlags.Ephemeral };
      try {
        if (interaction.deferred || interaction.replied) await interaction.followUp(payload);
        else await interaction.reply(payload);
      } catch {}
    }
  }
});

const shutdown = (signal) => {
  logger.info({ signal }, 'shutting down');
  try { shutdownAll(); } catch {}
  client.destroy().finally(() => process.exit(0));
};
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('unhandledRejection', (e) => logger.error({ err: e?.message, stack: e?.stack }, 'unhandled rejection'));
process.on('uncaughtException', (e) => logger.error({ err: e?.message, stack: e?.stack }, 'uncaught exception'));

client.login(config.token).catch((err) => {
  logger.fatal({ err: err.message }, 'Discord login failed');
  process.exit(1);
