app.post('/api/start', async (req, res) => {
  const service = req.body?.service === 'admin' ? config.admin.adminService : config.admin.botService;
  try {
    const out = await runCmd('systemctl', ['--user', 'start', service]);
    res.json({ ok: true, service, out });
