app.post('/api/git-pull', async (_req, res) => {
  try {
    const pullOut = await runCmd('git', ['-C', REPO_ROOT, 'pull', '--ff-only']);
    let installOut = '';
    try {
      installOut = await runCmd('bash', ['-lc', `cd ${shellQuote(REPO_ROOT)} && npm install --omit=dev --no-audit --no-fund`]);
    } catch (e) {
      installOut = `npm install warning: ${e.message}`;
    }
    let restartOut = '';
    try {
      restartOut = await runCmd('systemctl', ['--user', 'restart', config.admin.botService]);
    } catch (e) {
      restartOut = `restart warning: ${e.message}`;
    }
    res.json({ ok: true, pull: pullOut, install: installOut, restart: restartOut });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

const port = config.admin.port;
const bind = config.admin.bind;
app.listen(port, bind, () => {
  logger.info({ url: `http://${bind}:${port}/` }, 'admin panel listening');
});

async function systemctlStatus(service) {
  try {
    const { stdout } = await execAsync(
      `systemctl --user show ${shellQuote(service)} --property=ActiveState,SubState,MainPID,ExecMainStartTimestamp,UnitFileState`,
    );
    const out = {};
    for (const line of stdout.trim().split('\n')) {
      const i = line.indexOf('=');
      if (i > 0) out[line.slice(0, i)] = line.slice(i + 1);
    }
    return { name: service, ...out };
  } catch (e) {
    return { name: service, error: e.message };
  }
}

function runCmd(cmd, args) {
  return new Promise((resolve, reject) => {
    const proc = spawn(cmd, args);
    let stdout = '', stderr = '';
    proc.stdout.on('data', (c) => (stdout += c));
    proc.stderr.on('data', (c) => (stderr += c));
    proc.on('error', reject);
    proc.on('close', (code) => {
      if (code !== 0) return reject(new Error(`${cmd} exit ${code}: ${stderr.trim() || stdout.trim()}`));
      resolve((stdout + stderr).trim());
    });
  });
}

function shellQuote(s) {
  return `'${String(s).replace(/'/g, `'\\''`)}'`;
}

function clampInt(v, def, min, max) {
  const n = parseInt(v, 10);
  if (isNaN(n)) return def;
  return Math.max(min, Math.min(max, n));
}

import 'dotenv/config';

function isUnset(v) {
  return !v || v === '' || /^your-/i.test(v);
}

export const config = {
  token: process.env.DISCORD_TOKEN,
  clientId: process.env.DISCORD_CLIENT_ID,
  guildId: process.env.DISCORD_GUILD_ID,
  botCommandsChannelId: process.env.BOT_COMMANDS_CHANNEL_ID,
  ytdlpPath: process.env.YTDLP_PATH || 'yt-dlp',
  logLevel: process.env.LOG_LEVEL || 'info',
  admin: {
    port: parseInt(process.env.ADMIN_PORT || '8787', 10),
    user: process.env.ADMIN_USER || 'admin',
    password: process.env.ADMIN_PASSWORD || 'change-me',
    bind: process.env.ADMIN_BIND || '0.0.0.0',
    botService: process.env.BOT_SERVICE || 'discord-music-bot.service',
    adminService: process.env.ADMIN_SERVICE || 'discord-music-bot-admin.service',
  },
};

export function validateBotConfig() {
  const required = ['token', 'clientId', 'guildId', 'botCommandsChannelId'];
  const missing = required.filter((k) => isUnset(config[k]));
  if (missing.length) {
    throw new Error(
      `Missing or unset env vars: ${missing.map(k => k.toUpperCase()).join(', ')}. Edit .env on the server.`,
    );
  }
}

