import pino from 'pino';
import { config } from './config.js';

const usePretty =
  process.env.LOG_PRETTY === '1' ||
  (process.env.LOG_PRETTY !== '0' && process.stdout.isTTY);

export const logger = pino({
  level: process.env.LOG_LEVEL || config.logLevel || 'info',
  base: { svc: 'ratmusic' },
  transport: usePretty
    ? {
        target: 'pino-pretty',
        options: {
          colorize: true,
          translateTime: 'SYS:HH:MM:ss.l',
          ignore: 'pid,hostname,svc',
          singleLine: false,
        },
      }
    : undefined,
});

let __reqCounter = 0;
export function nextRequestId() {
  __reqCounter = (__reqCounter + 1) & 0xfffff;
  return `${Date.now().toString(36)}-${__reqCounter.toString(36)}`;
}

import {
  VoiceConnectionStatus,
  AudioPlayerStatus,
  NetworkingStatusCode,
} from '@discordjs/voice';

const NETWORKING_CODE_NAMES = (() => {
  if (NetworkingStatusCode && typeof NetworkingStatusCode === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(NetworkingStatusCode)) {
      if (typeof v === 'number') out[v] = k;
    }
    return out;
  }
  return {
    0: 'OpeningWs',
    1: 'Identifying',
    2: 'UdpHandshaking',
    3: 'SelectingProtocol',
    4: 'Ready',
    5: 'Resuming',
    6: 'Closed',
  };
})();

function describeNetworking(state) {
  if (!state || !state.networking) return null;
  const ns = state.networking.state;
  return {
    code: ns?.code,
    name: ns?.code != null ? NETWORKING_CODE_NAMES[ns.code] || String(ns.code) : null,
    udpRemote: ns?.connectionData
      ? { ip: ns.connectionData.ip, port: ns.connectionData.port }
      : ns?.connectionOptions
        ? { ip: ns.connectionOptions.serverIp, port: ns.connectionOptions.serverPort }
        : null,
    encryptionMode: ns?.connectionData?.encryptionMode || null,
    sessionId: ns?.sessionId || ns?.connectionOptions?.sessionId || null,
  };
}

function describeConnState(state) {
  if (!state) return null;
  return {
    status: state.status,
    reason: state.reason,
    closeCode: state.closeCode,
    networking: describeNetworking(state),
  };
}

/**
 * Attach exhaustive lifecycle logging to a VoiceConnection.
 *
 * @param {import('@discordjs/voice').VoiceConnection} connection
 * @param {import('pino').Logger} log  child logger (already bound with reqId, guildId, voiceChannelId)
 */
export function attachConnectionTelemetry(connection, log) {
  log.info(
    { initialStatus: connection.state?.status },
    'voice: joinVoiceChannel called',
  );

  connection.on('stateChange', (oldState, newState) => {
    log.info(
      {
        from: oldState.status,
        to: newState.status,
        reason: newState.reason,
        closeCode: newState.closeCode,
        networking: describeNetworking(newState),
      },
      'voice: connection state change',
    );
  });

  connection.on('debug', (msg) => {
    log.debug({ msg }, 'voice: connection debug');
  });

  connection.on('error', (err) => {
    log.error({ err: err?.message, stack: err?.stack }, 'voice: connection error');
  });

  for (const status of Object.values(VoiceConnectionStatus)) {
    connection.on(status, () => {
      log.debug(
        { status, networking: describeNetworking(connection.state) },
        `voice: status event ${status}`,
      );
    });
  }
}

/**
 * Attach exhaustive lifecycle logging to an AudioPlayer.
 *
 * @param {import('@discordjs/voice').AudioPlayer} player
 * @param {import('pino').Logger} log
 */
export function attachPlayerTelemetry(player, log) {
  let lastTransitionAt = Date.now();
  player.on('stateChange', (oldState, newState) => {
    const now = Date.now();
    const elapsedMs = now - lastTransitionAt;
    lastTransitionAt = now;
    log.info(
      {
        from: oldState.status,
        to: newState.status,
        elapsedMs,
        playbackDurationMs: newState.playbackDuration,
        missedFrames: newState.resource?.audioPlayer?.checkPlayable === undefined
          ? undefined
          : undefined,
      },
      'audio: player state change',
    );
  });
  player.on('debug', (msg) => log.debug({ msg }, 'audio: player debug'));
  player.on('error', (err) => {
    log.error(
      {
        err: err?.message,
        stack: err?.stack,
        resourceMeta: err?.resource?.metadata,
      },
      'audio: player error',
    );
  });
  for (const status of Object.values(AudioPlayerStatus)) {
    player.on(status, () => log.debug({ status }, `audio: status event ${status}`));
  }
}

export { describeNetworking, describeConnState };

import {
  joinVoiceChannel,
  createAudioPlayer,
  createAudioResource,
  AudioPlayerStatus,
  VoiceConnectionStatus,
  StreamType,
  entersState,
  NoSubscriberBehavior,
} from '@discordjs/voice';
import { spawnAudioStream } from './resolver.js';
import { logger } from '../logger.js';
import {
  attachConnectionTelemetry,
  attachPlayerTelemetry,
  describeConnState,
} from './voiceTelemetry.js';

const VOICE_READY_TIMEOUT_MS = parseInt(
  process.env.VOICE_READY_TIMEOUT_MS || '20000',
  10,
);

/**
 * Per-guild music state.
 */
class GuildMusic {
  constructor(guildId) {
    this.guildId = guildId;
    this.queue = [];
    this.current = null;
    this.connection = null;
    this.player = null;
    this.textChannel = null;
    this.voiceChannelId = null;
    this.currentProc = null;
    this.destroyed = false;
    this.log = logger.child({ guildId });
  }

  ensurePlayer(reqLog = this.log) {
    if (this.player) return this.player;
    this.player = createAudioPlayer({
      behaviors: { noSubscriber: NoSubscriberBehavior.Pause },
    });
    attachPlayerTelemetry(this.player, this.log.child({ component: 'player' }));

    this.player.on('error', (err) => {
      this.log.error({ err: err.message, stack: err.stack }, 'audio player error');
      this._safeNotify(`Playback error: ${err.message}`);
      this._advance();
    });
    this.player.on(AudioPlayerStatus.Idle, () => {
      this._advance();
    });
    return this.player;
  }

  /**
   * @param {*} voiceChannel
   * @param {*} textChannel
   * @param {{log?: import('pino').Logger}} [opts]
   */
  async connect(voiceChannel, textChannel, opts = {}) {
    const reqLog = (opts.log || this.log).child({ voiceChannelId: voiceChannel.id });
    this.textChannel = textChannel;

    if (this.connection && this.voiceChannelId === voiceChannel.id) {
      reqLog.info(
        { reusing: true, status: this.connection.state?.status },
        'voice: reusing existing connection',
      );
      return this.connection;
    }

    if (this.connection) {
      reqLog.info(
        { from: this.voiceChannelId, to: voiceChannel.id },
        'voice: switching channels, destroying old connection',
      );
      try { this.connection.destroy(); } catch (e) {
        reqLog.warn({ err: e.message }, 'voice: error destroying old connection');
      }
      this.connection = null;
    }

    reqLog.info(
      {
        guildId: voiceChannel.guild.id,
        channelId: voiceChannel.id,
        channelName: voiceChannel.name,
        bitrate: voiceChannel.bitrate,
        rtcRegion: voiceChannel.rtcRegion,
        userLimit: voiceChannel.userLimit,
        memberCount: voiceChannel.members?.size,
        readyTimeoutMs: VOICE_READY_TIMEOUT_MS,
      },
      'voice: about to call joinVoiceChannel',
    );

    this.connection = joinVoiceChannel({
      channelId: voiceChannel.id,
      guildId: voiceChannel.guild.id,
      adapterCreator: voiceChannel.guild.voiceAdapterCreator,
      selfDeaf: true,
      selfMute: false,
    });
    this.voiceChannelId = voiceChannel.id;

    attachConnectionTelemetry(this.connection, reqLog.child({ component: 'voiceConn' }));

    this.connection.on(VoiceConnectionStatus.Disconnected, async (oldState, newState) => {
      reqLog.warn(
        {
          oldStatus: oldState.status,
          newStatus: newState.status,
          reason: newState.reason,
          closeCode: newState.closeCode,
        },
        'voice: disconnected, attempting recovery',
      );
      try {
        await Promise.race([
          entersState(this.connection, VoiceConnectionStatus.Signalling, 5000),
          entersState(this.connection, VoiceConnectionStatus.Connecting, 5000),
        ]);
        reqLog.info('voice: recovered from disconnect');
      } catch (e) {
        reqLog.warn({ err: e?.message }, 'voice: recovery failed, destroying');
        this.destroy();
      }
    });

    this.connection.subscribe(this.ensurePlayer(reqLog));
    reqLog.debug('voice: subscribed audio player to connection');

    const startedAt = Date.now();
    try {
      await entersState(this.connection, VoiceConnectionStatus.Ready, VOICE_READY_TIMEOUT_MS);
      const elapsedMs = Date.now() - startedAt;
      reqLog.info(
        {
          elapsedMs,
          state: describeConnState(this.connection.state),
        },
        'voice: connection READY',
      );
    } catch (e) {
      const elapsedMs = Date.now() - startedAt;
      reqLog.error(
        {
          err: e?.message,
          stack: e?.stack,
          elapsedMs,
          finalState: describeConnState(this.connection.state),
        },
        'voice: timed out waiting for READY',
      );
      this.destroy();
      throw e;
    }
    return this.connection;
  }

  enqueue(track) {
    this.queue.push(track);
  }

  enqueueNext(track) {
    this.queue.unshift(track);
  }

  async maybeStart(reqLog = this.log) {
    if (!this.player) {
      reqLog.debug('maybeStart: no player yet');
      return;
    }
    if (this.current) {
      reqLog.debug({ current: this.current.title }, 'maybeStart: already playing');
      return;
    }
    if (this.queue.length === 0) {
      reqLog.debug('maybeStart: queue empty');
      return;
    }
    await this._playNext(reqLog);
  }

  async _playNext(reqLog = this.log) {
    const next = this.queue.shift();
    if (!next) {
      this.current = null;
      reqLog.debug('_playNext: nothing to play');
      return;
    }
    this.current = next;
    reqLog.info(
      {
        title: next.title,
        url: next.webpageUrl,
        durationSec: next.durationSec,
        requestedBy: next.requestedBy,
      },
      'play: starting next track',
    );

    try {
      const proc = spawnAudioStream(next.webpageUrl, reqLog.child({ component: 'ytdlp-stream' }));
      this.currentProc = proc;
      const resource = createAudioResource(proc.stdout, { inputType: StreamType.Arbitrary });
      this.ensurePlayer(reqLog).play(resource);
      reqLog.info({ title: next.title }, 'play: audio resource handed to player');
      this._safeNotify(`Now playing: **${escapeMd(next.title)}**`);
    } catch (e) {
      reqLog.error({ err: e.message, stack: e.stack }, 'play: failed to start track');
      this._safeNotify(`Failed to play **${escapeMd(next.title)}**: ${e.message}`);
      this._advance();
    }
  }

  _advance() {
    this._killCurrentProc();
    this.current = null;
    if (this.queue.length === 0) {
      this.log.debug('advance: queue exhausted, staying connected idle');
      return;
    }
    this._playNext();
  }

  _killCurrentProc() {
    if (this.currentProc) {
      try { this.currentProc.kill('SIGKILL'); } catch {}
      this.currentProc = null;
    }
  }

  skip() {
    const skipped = this.current;
    if (!skipped && this.queue.length === 0) return null;
    if (this.player) this.player.stop(true);
    this._killCurrentProc();
    return skipped;
  }

  removeIndex(oneBased) {
    const i = oneBased - 1;
    if (i < 0 || i >= this.queue.length) return null;
    return this.queue.splice(i, 1)[0];
  }

  removeRange(startOne, endOne) {
    const start = Math.max(1, startOne) - 1;
    const end = Math.min(this.queue.length, endOne);
    if (start >= this.queue.length || end <= start) return [];
    return this.queue.splice(start, end - start);
  }

  stopAndLeave() {
    this.queue = [];
    this.current = null;
    this._killCurrentProc();
    if (this.player) {
      try { this.player.stop(true); } catch {}
    }
    if (this.connection) {
      try { this.connection.destroy(); } catch {}
      this.connection = null;
      this.voiceChannelId = null;
    }
  }

  destroy() {
    this.destroyed = true;
    this.stopAndLeave();
  }

  _safeNotify(msg) {
    if (!this.textChannel) return;
    this.textChannel.send({ content: msg }).catch((e) => {
      this.log.warn({ err: e.message }, 'failed to send notify message');
    });
  }
}

function escapeMd(s) {
  return String(s).replace(/([*_~`>|\\])/g, '\\$1');
}

const guilds = new Map();

export function getMusic(guildId) {
  let g = guilds.get(guildId);
  if (!g) {
    g = new GuildMusic(guildId);
    guilds.set(guildId, g);
  }
  return g;
}

export function shutdownAll() {
  for (const g of guilds.values()) {
    try { g.destroy(); } catch {}
  }
  guilds.clear();
}

