function runYtdlpJson(args, log = logger) {
  return new Promise((resolve, reject) => {
    const startedAt = Date.now();
    log.debug({ bin: config.ytdlpPath, args }, 'yt-dlp: spawn (resolve)');
    const proc = spawn(config.ytdlpPath, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    let err = '';
    proc.stdout.on('data', (c) => (out += c));
    proc.stderr.on('data', (c) => (err += c));
    proc.on('error', (e) => {
      log.error({ err: e.message }, 'yt-dlp: spawn error (resolve)');
      reject(e);
    });
    proc.on('close', (code) => {
      const elapsedMs = Date.now() - startedAt;
      const errTail = err.trim().slice(-1500);
      if (code !== 0) {
        log.warn({ code, elapsedMs, errTail }, 'yt-dlp: non-zero exit (resolve)');
        return reject(new Error(`yt-dlp exit ${code}: ${err.trim()}`));
      }
      try {
        const firstLine = out.trim().split('\n').filter(Boolean)[0];
        if (!firstLine) {
          log.warn({ elapsedMs, errTail }, 'yt-dlp: empty output (resolve)');
          return reject(new Error('yt-dlp returned no data'));
        }
        const parsed = JSON.parse(firstLine);
        log.debug(
          { elapsedMs, title: parsed.title, durationSec: parsed.duration },
          'yt-dlp: resolve OK',
        );
        resolve(parsed);
      } catch (e) {
        log.error({ err: e.message, elapsedMs }, 'yt-dlp: JSON parse failed (resolve)');
        reject(new Error(`yt-dlp JSON parse failed: ${e.message}`));
      }
    });
  });
}

