import { getMusic } from '../music/manager.js';
import { resolveQuery, formatDuration } from '../music/resolver.js';
import { logger, nextRequestId } from '../logger.js';

function truncate(s, n) {
  s = String(s);
  return s.length <= n ? s : s.slice(0, n - 1) + '…';
}

/**
 * Shared logic for /play and /playnext.
 *
 * @param {import('discord.js').ChatInputCommandInteraction} interaction
 * @param {{ atFront: boolean }} opts
 */
export async function addToQueue(interaction, { atFront }) {
  const reqId = nextRequestId();
  const cmd = atFront ? 'playnext' : 'play';
  const reqLog = logger.child({
    reqId,
    cmd,
    user: interaction.user?.tag,
    userId: interaction.user?.id,
    guildId: interaction.guildId,
    interactionId: interaction.id,
  });
  reqLog.info('cmd: received');

  try {
    await interaction.deferReply();
    reqLog.debug('cmd: deferReply ok');
  } catch (e) {
    reqLog.warn(
      { err: e.message, code: e.code },
      'cmd: deferReply failed (interaction expired before handler ran)',
    );
    return;
  }

  const rawQuery = interaction.options.getString('query') ?? '';
  const query = rawQuery.trim();
  if (!query) {
    reqLog.warn('cmd: empty query');
    return interaction.editReply({
      content:
        'Please supply a query (URL or search text). If Discord did not show the input field, refresh your client (Ctrl+R) and try again.',
    });
  }

  const member = interaction.member;
  const voice = member?.voice?.channel;
  if (!voice) {
    reqLog.warn('cmd: user not in voice channel');
    return interaction.editReply({
      content: 'You need to be in a voice channel.',
    });
  }
  reqLog.info(
    {
      voiceChannelId: voice.id,
      voiceChannelName: voice.name,
      query: truncate(query, 200),
    },
    'cmd: validated, resolving',
  );

  let track;
  try {
    track = await resolveQuery(query, interaction.user.id, reqLog);
    reqLog.info(
      {
        title: track.title,
        durationSec: track.durationSec,
        webpageUrl: track.webpageUrl,
      },
      'cmd: resolved track',
    );
  } catch (e) {
    reqLog.warn({ err: e.message }, 'cmd: resolve failed');
    return interaction.editReply({
      content: `Could not resolve **${truncate(query, 100)}**: ${e.message}`,
    });
  }

  const music = getMusic(interaction.guildId);

  try {
    await music.connect(voice, interaction.channel, { log: reqLog });
  } catch (e) {
    reqLog.error({ err: e.message }, 'cmd: voice connect failed');
    return interaction.editReply({
      content: `Could not join your voice channel: ${e.message}`,
    });
  }

  if (atFront) {
    music.enqueueNext(track);
  } else {
    music.enqueue(track);
  }
  reqLog.info(
    { atFront, queueLen: music.queue.length, hasCurrent: !!music.current },
    'cmd: enqueued',
  );

  const wasIdle = !music.current;
  await music.maybeStart(reqLog);

  let where;
  if (wasIdle) {
    where = 'Now playing';
  } else if (atFront) {
    where = 'Playing next';
  } else {
    const position = music.queue.length;
    where = `Added to queue (position **#${position}**)`;
  }

  await interaction.editReply({
    content: `${where}: **${truncate(track.title, 200)}** \`[${formatDuration(track.durationSec)}]\``,
  });
  reqLog.info({ where }, 'cmd: replied OK');
}

import { Client, GatewayIntentBits, Events, MessageFlags } from 'discord.js';
import { generateDependencyReport } from '@discordjs/voice';
import { config, validateBotConfig } from './config.js';

validateBotConfig();
import { logger, nextRequestId } from './logger.js';
import { shutdownAll } from './music/manager.js';
import { handleButton } from './interactions/buttons.js';

import * as play from './commands/play.js';
import * as playnext from './commands/playnext.js';
import * as skip from './commands/skip.js';
import * as queueCmd from './commands/queue.js';
import * as stop from './commands/stop.js';
import * as remove from './commands/remove.js';

const commands = new Map([
  [play.data.name, play],
  [playnext.data.name, playnext],
  [skip.data.name, skip],
  [queueCmd.data.name, queueCmd],
  [stop.data.name, stop],
  [remove.data.name, remove],
]);

logger.info(
  { report: generateDependencyReport().split('\n') },
  'voice: @discordjs/voice dependency report',
);

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildVoiceStates,
  ],
});

client.once(Events.ClientReady, (c) => {
  logger.info(
    {
      tag: c.user.tag,
      id: c.user.id,
      guildCount: c.guilds.cache.size,
    },
    'Discord client ready',
  );
});

client.on(Events.Error, (e) =>
  logger.error({ err: e?.message, stack: e?.stack }, 'discord client error'),
);
client.on(Events.Warn, (msg) => logger.warn({ msg }, 'discord client warn'));
if (process.env.DISCORD_DEBUG === '1') {
  client.on(Events.Debug, (msg) => logger.debug({ msg }, 'discord client debug'));
}

client.on(Events.InteractionCreate, async (interaction) => {
  const reqLog = logger.child({
    interactionId: interaction.id,
    interactionType: interaction.type,
    commandName: interaction.commandName,
    customId: interaction.customId,
    user: interaction.user?.tag,
    guildId: interaction.guildId,
    channelId: interaction.channelId,
  });
  reqLog.debug('interaction: received');
  try {
    if (interaction.isChatInputCommand()) {
      if (interaction.channelId !== config.botCommandsChannelId) {
        reqLog.warn(
          { expected: config.botCommandsChannelId },
          'interaction: wrong channel, rejecting',
        );
        return interaction.reply({
          content: `Please use this command in <#${config.botCommandsChannelId}>.`,
          flags: MessageFlags.Ephemeral,
        });
      }
      const cmd = commands.get(interaction.commandName);
      if (!cmd) {
        reqLog.warn('interaction: unknown command');
        return interaction.reply({ content: 'Unknown command.', flags: MessageFlags.Ephemeral });
      }
      await cmd.execute(interaction);
      return;
    }

    if (interaction.isButton()) {
      if (interaction.channelId !== config.botCommandsChannelId) {
        reqLog.warn('interaction: button in wrong channel');
        return interaction.reply({
          content: `Please use bot controls in <#${config.botCommandsChannelId}>.`,
          flags: MessageFlags.Ephemeral,
        });
      }
      await handleButton(interaction);
      return;
    }
  } catch (err) {
    reqLog.error(
      { err: err?.message, stack: err?.stack },
      'interaction handler crashed',
    );
    if (interaction.isRepliable()) {
      const payload = { content: `Internal error: ${err?.message || 'unknown'}`, flags: MessageFlags.Ephemeral };
      try {
        if (interaction.deferred || interaction.replied) await interaction.followUp(payload);
        else await interaction.reply(payload);
      } catch {}
    }
  }
});

const shutdown = (signal) => {
  logger.info({ signal }, 'shutting down');
  try { shutdownAll(); } catch {}
  client.destroy().finally(() => process.exit(0));
};
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('unhandledRejection', (e) => logger.error({ err: e?.message, stack: e?.stack }, 'unhandled rejection'));
process.on('uncaughtException', (e) => logger.error({ err: e?.message, stack: e?.stack }, 'uncaught exception'));

logger.info({ rid: nextRequestId() }, 'logging in to Discord');
client.login(config.token).catch((err) => {
  logger.fatal({ err: err.message }, 'Discord login failed');
  process.exit(1);
});

import { vi } from 'vitest';

export function makeFakeLogger() {
  const log = {
    info: vi.fn(),
    warn: vi.fn(),
    error: vi.fn(),
    debug: vi.fn(),
    fatal: vi.fn(),
    trace: vi.fn(),
  };
  log.child = vi.fn(() => log);
  return log;
}

export const fakeLoggerModule = {
  logger: makeFakeLogger(),
  nextRequestId: () => 'test-req-id',
};

